<template>
  <main ref="root" class="news-detail-page" :style="{ '--reading-progress': `${progress}%` }">
    <div class="reading-progress" aria-hidden="true"><span></span></div>
    <section v-if="item" class="article-shell article-head" data-reveal>
      <button class="article-back" type="button" @click="backToList"><ArrowLeft aria-hidden="true" /> {{ isEn ? 'Back to insights' : '返回资讯列表' }}</button>
      <p class="article-kicker">{{ localized(item.categoryLabel, item.categoryLabelEn) }}</p>
      <h1>{{ localized(item.title, item.titleEn) }}</h1>
      <p class="article-summary">{{ localized(item.summary, item.summaryEn) }}</p>
      <div class="article-meta"><time :datetime="item.publishedAt">{{ item.publishedAt }}</time><span>{{ item.author || (isEn ? 'YUNZHAN TEAM' : '耘栈团队') }}</span><span>{{ source === 'mock' ? (isEn ? 'Demo data' : '演示数据') : (isEn ? 'Published' : '正式内容') }}</span></div>
    </section>
    <section v-if="item" class="article-shell article-main" data-reveal>
      <figure class="article-cover"><img :src="item.cover?.src" :alt="localized(item.title, item.titleEn)" loading="eager"><figcaption>{{ localized(item.sourceLabel, item.sourceLabel) }}<a v-if="item.sourceUrl" :href="item.sourceUrl" target="_blank" rel="noopener noreferrer">{{ isEn ? 'Source' : '来源' }}</a></figcaption></figure>
      <article class="article-rich" v-html="safeBody"></article>
      <footer class="article-footer"><a class="article-link" @click.prevent="backToList" href="#">{{ isEn ? 'Back to all insights' : '返回全部资讯' }} <ArrowLeft aria-hidden="true" /></a></footer>
    </section>
    <section v-else-if="errorType === 'not-found'" class="article-empty article-shell" data-reveal><p class="article-kicker">404 / {{ isEn ? 'NOT FOUND' : '未找到' }}</p><h1>{{ isEn ? 'This article is unavailable.' : '暂未找到这篇资讯。' }}</h1><p>{{ isEn ? 'The ID may be incorrect or the article is no longer published.' : '资讯 ID 不正确，或文章尚未发布。' }}</p><button type="button" class="article-link" @click="backToList">{{ isEn ? 'Back to insights' : '返回资讯列表' }} <ArrowLeft aria-hidden="true" /></button></section>
    <section v-else-if="errorType" class="article-empty article-shell" data-reveal><p class="article-kicker">{{ isEn ? 'TEMPORARY ERROR' : '暂时不可用' }}</p><h1>{{ isEn ? 'Insights could not be loaded.' : '资讯暂时无法加载。' }}</h1><p>{{ isEn ? 'Please try again, or return to the list.' : '请重试，或先返回资讯列表。' }}</p><div><button type="button" class="article-link" @click="loadArticle">{{ isEn ? 'Retry' : '重新加载' }}</button><button type="button" class="article-link" @click="backToList">{{ isEn ? 'Back to list' : '返回列表' }}</button></div></section>
    <div v-else class="article-loading article-shell">{{ isEn ? 'Loading insight…' : '资讯加载中…' }}</div>
  </main>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowLeft } from '@element-plus/icons-vue'
import { useRoute, useRouter } from 'vue-router'
import { getNews } from '@/repositories/content'
const route = useRoute(); const router = useRouter(); const root = ref(null); const item = ref(null); const source = ref('api'); const errorType = ref(''); const progress = ref(0); let revealObserver
const isEn = computed(() => route.path.startsWith('/en/')); const localized = (zh, en) => isEn.value ? (en || zh || '') : (zh || en || ''); const safeHtml = html => { if (typeof window === 'undefined') return ''; const doc = new DOMParser().parseFromString(String(html || ''), 'text/html'); doc.querySelectorAll('script,style,iframe,object,embed,form,link,meta').forEach(node => node.remove()); doc.body.querySelectorAll('*').forEach(node => Array.from(node.attributes).forEach(attribute => { const name = attribute.name.toLowerCase(); const value = attribute.value.trim(); if (name.startsWith('on') || name === 'style' || ((name === 'href' || name === 'src') && !/^(https?:|\/|#)/i.test(value))) node.removeAttribute(attribute.name) })); return doc.body.innerHTML }
const safeBody = computed(() => safeHtml(isEn.value ? (item.value?.bodyHtmlEn || item.value?.bodyHtml) : item.value?.bodyHtml)); const backToList = () => router.push(isEn.value ? '/en/news' : '/news')
const updateProgress = () => { const max = document.documentElement.scrollHeight - window.innerHeight; progress.value = max > 0 ? Math.min(100, Math.max(0, window.scrollY / max * 100)) : 0 }
async function loadArticle () { item.value = null; errorType.value = ''; try { const result = await getNews({ id: String(route.params.id) }); item.value = result.item; source.value = result.source } catch (error) { errorType.value = error?.type === 'not-found' ? 'not-found' : 'network' } }
onMounted(async () => { window.addEventListener('scroll', updateProgress, { passive: true }); await loadArticle(); updateProgress(); revealObserver = 'IntersectionObserver' in window ? new IntersectionObserver(entries => entries.forEach(entry => entry.target.classList.toggle('is-visible', entry.isIntersecting)), { threshold: .12 }) : null; if (revealObserver) root.value?.querySelectorAll('[data-reveal]').forEach(node => revealObserver.observe(node)); else root.value?.querySelectorAll('[data-reveal]').forEach(node => node.classList.add('is-visible')) })
onBeforeUnmount(() => { revealObserver?.disconnect(); window.removeEventListener('scroll', updateProgress) })
</script>

<style scoped>
.news-detail-page{min-height:100vh;background:var(--color-bg);color:var(--color-ink);padding-bottom:140px}.article-shell{width:min(88%,900px);margin-inline:auto}.reading-progress{position:fixed;z-index:20;top:76px;left:0;width:100%;height:2px;background:color-mix(in srgb,var(--color-ink) 12%,transparent)}.reading-progress span{display:block;width:var(--reading-progress);height:100%;background:var(--color-accent);transition:width .15s linear}.article-head{padding-top:150px;padding-bottom:70px}.article-back{display:inline-flex;align-items:center;gap:10px;margin-bottom:90px;padding:0;border:0;background:none;color:var(--color-ink-soft);font:inherit;cursor:pointer}.article-back svg,.article-link svg{width:17px}.article-kicker{color:var(--color-accent);font-size:11px;letter-spacing:.16em;text-transform:uppercase}.article-head h1{max-width:850px;margin:24px 0;font-size:clamp(48px,7vw,90px);font-weight:500;line-height:1.02;letter-spacing:-.05em}.article-summary{max-width:650px;color:var(--color-ink-body);font-size:20px;line-height:1.75}.article-meta{display:flex;flex-wrap:wrap;gap:25px;margin-top:38px;color:var(--color-ink-soft);font-size:12px;letter-spacing:.08em}.article-main{opacity:0;transform:translateY(30px);transition:opacity .8s ease,transform .8s ease}.article-main.is-visible{opacity:1;transform:none}.article-cover{margin:0 0 78px;overflow:hidden;background:var(--color-surface-soft)}.article-cover img{display:block;width:100%;max-height:580px;object-fit:cover;transition:transform 1.1s cubic-bezier(.2,.7,.2,1)}.article-cover:hover img{transform:scale(1.04)}.article-cover figcaption{display:flex;justify-content:space-between;gap:20px;padding:13px 16px;color:var(--color-ink-soft);font-size:11px}.article-cover a{color:var(--color-ink);text-decoration:underline}.article-rich{color:var(--color-ink-body);font-size:17px;line-height:2}.article-rich :deep(h2){margin:54px 0 17px;color:var(--color-ink);font-size:34px;font-weight:500;line-height:1.2}.article-rich :deep(p){margin:0 0 23px}.article-rich :deep(a){color:var(--color-accent)}.article-rich :deep(ul),.article-rich :deep(ol){padding-left:24px}.article-footer{margin-top:80px;padding-top:22px;border-top:1px solid var(--color-line)}.article-link{display:inline-flex;align-items:center;gap:12px;padding:14px 0;border:0;background:none;color:var(--color-ink);font:inherit;text-decoration:none;cursor:pointer}.article-empty{padding-top:180px;min-height:70vh}.article-empty h1{max-width:780px;margin:22px 0;font-size:clamp(46px,7vw,90px);font-weight:500;line-height:1}.article-empty p:not(.article-kicker){color:var(--color-ink-soft);font-size:18px}.article-empty .article-link+ .article-link{margin-left:25px}.article-loading{padding-top:190px;color:var(--color-ink-soft)}@media(max-width:760px){.article-shell{width:min(88%,640px)}.article-head{padding-top:120px;padding-bottom:55px}.article-back{margin-bottom:62px}.article-summary{font-size:17px}.article-meta{gap:12px 18px;margin-top:28px}.article-cover{margin-bottom:58px}.article-rich{font-size:16px}.article-rich :deep(h2){font-size:28px;margin-top:42px}.reading-progress{top:64px}.article-empty{padding-top:140px}}@media(prefers-reduced-motion:reduce){.article-main{opacity:1;transform:none}.article-cover img{transition:none}}
</style>
